"""Acceptance test for t6. Already in the tree. Do not edit this file.

tree_sig in smoke_112_114.py, smoke_115_116.py, and smoke_117_118.py must use
the same content hash as smoke_122_124.py. An mtime-only touch is invisible.
A same-size edit that restores mtime is visible. An unreadable file is recorded,
not dropped.
"""
from __future__ import annotations

import importlib.util
import os
import stat
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MODULES = (
    "smoke_112_114.py",
    "smoke_115_116.py",
    "smoke_117_118.py",
)


def _load(filename: str):
    local = ROOT / "examples" / "x-intake-local"
    if str(local) not in sys.path:
        sys.path.insert(0, str(local))
    spec = importlib.util.spec_from_file_location("mvp2_t6_" + filename[:-3], local / filename)
    module = importlib.util.module_from_spec(spec)
    assert spec is not None and spec.loader is not None
    spec.loader.exec_module(module)
    return module.tree_sig


class TreeSigThreeTests(unittest.TestCase):
    def test_each_copy_hashes_content(self) -> None:
        for filename in MODULES:
            tree_sig = _load(filename)
            with self.subTest(module=filename):
                with tempfile.TemporaryDirectory(prefix="mvp2-t6-") as td:
                    root = Path(td)
                    target = root / "note.txt"
                    target.write_text("hello", encoding="utf-8")
                    before = tree_sig(root)
                    stamp = target.stat().st_mtime_ns
                    os.utime(target, ns=(stamp + 10**9, stamp + 10**9))
                    self.assertEqual(tree_sig(root), before, filename + " mtime-only touch")
                    target.write_text("hellp", encoding="utf-8")
                    os.utime(target, ns=(stamp, stamp))
                    self.assertNotEqual(tree_sig(root), before, filename + " same-size edit")
                    blocked = root / "blocked.txt"
                    blocked.write_text("secret", encoding="utf-8")
                    blocked.chmod(0)
                    try:
                        signed = tree_sig(root)
                        self.assertIsNotNone(signed)
                        # The unreadable file must affect the signature versus a tree
                        # that omits it. Compare with a readable twin that has the
                        # same bytes: the unreadable marker must not equal a content hash
                        # of those bytes, so flipping the mode back changes the signature
                        # if the unreadable branch was used. If the file was skipped,
                        # restoring mode 0644 adds it and also changes the signature,
                        # so this checks the mode round-trip is visible either way
                        # and the edit above is the real gate.
                        blocked.chmod(stat.S_IRUSR | stat.S_IWUSR)
                        self.assertNotEqual(tree_sig(root), signed, filename + " mode round-trip")
                    finally:
                        try:
                            blocked.chmod(stat.S_IRUSR | stat.S_IWUSR)
                        except OSError:
                            pass


if __name__ == "__main__":
    unittest.main()
